import React, { useRef } from 'react';
import html2canvas from 'html2canvas';
import { questions } from '../data/questions';

const archetypeMeta = {
  peacefulSoul: {
    label: 'ผู้แสวงหาความสงบ',
    eng: 'The Peaceful Soul',
    hashtags: ['#สงบ', '#เรียบง่าย', '#ธรรมชาติ'],
    strengths: ['ใจเย็น', 'รักความสงบ', 'เข้าใจผู้อื่น'],
    color: 'from-[#e0eafc] to-[#cfdef3]',
    avatar: require('../avatars/peacefulSoul.png'),
    funeralStyle: 'งานศพที่เหมาะกับคุณคือพิธีเรียบง่าย อบอุ่น ท่ามกลางธรรมชาติหรือบ้านที่คุ้นเคย รายล้อมด้วยคนที่คุณรักและบรรยากาศสงบใจ'
  },
  lifeCelebrator: {
    label: 'ผู้เฉลิมฉลองชีวิต',
    eng: 'The Life Celebrator',
    hashtags: ['#สนุกสนาน', '#ร่าเริง', '#เฉลิมฉลอง'],
    strengths: ['ร่าเริง', 'สร้างแรงบันดาลใจ', 'เปิดใจ'],
    color: 'from-[#fceabb] to-[#f8b500]',
    avatar: require('../avatars/lifeCelebrator.png'),
    funeralStyle: 'งานศพที่เหมาะกับคุณคือพิธีที่เต็มไปด้วยเสียงหัวเราะ ดนตรี และเรื่องราวดี ๆ ให้ทุกคนได้ร่วมเฉลิมฉลองชีวิตของคุณ'
  },
  legacyGiver: {
    label: 'ผู้สร้างมรดก',
    eng: 'The Legacy Giver',
    hashtags: ['#แรงบันดาลใจ', '#มรดก', '#ความทรงจำ'],
    strengths: ['คิดลึกซึ้ง', 'สร้างสรรค์', 'มุ่งมั่น'],
    color: 'from-[#f5f7fa] to-[#c3cfe2]',
    avatar: require('../avatars/legacyGiver.png'),
    funeralStyle: 'งานศพที่เหมาะกับคุณคือพิธีที่เน้นการรำลึกถึงผลงานและแรงบันดาลใจที่คุณฝากไว้ มีการแบ่งปันเรื่องราวและของที่ระลึกที่มีความหมาย'
  },
  heartGuardian: {
    label: 'ผู้พิทักษ์หัวใจ',
    eng: 'The Heart Guardian',
    hashtags: ['#อบอุ่น', '#ครอบครัว', '#รัก'],
    strengths: ['ห่วงใย', 'อบอุ่น', 'เสียสละ'],
    color: 'from-[#fbc2eb] to-[#a6c1ee]',
    avatar: require('../avatars/heartGuardian.png'),
    funeralStyle: 'งานศพที่เหมาะกับคุณคือพิธีอบอุ่น รายล้อมด้วยครอบครัวและเพื่อนสนิท มีบรรยากาศแห่งความรักและการแบ่งปันความทรงจำดี ๆ'
  },
  quietPhilosopher: {
    label: 'นักคิดเงียบ',
    eng: 'The Quiet Philosopher',
    hashtags: ['#ลึกซึ้ง', '#ศรัทธา', '#เรียบง่าย'],
    strengths: ['ลึกซึ้ง', 'เข้าใจชีวิต', 'ถ่อมตน'],
    color: 'from-[#dbe6e4] to-[#b3c0c8]',
    avatar: require('../avatars/quietPhilosopher.png'),
    funeralStyle: 'งานศพที่เหมาะกับคุณคือพิธีเงียบสงบ เรียบง่าย มีการสะท้อนความหมายของชีวิตและศรัทธาในแบบที่คุณเชื่อ'
  }
};

const Summary = ({ answers, onRestart }) => {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Personality archetype analysis
  const analyzePersonality = () => {
    const archetypeScores = {
      peacefulSoul: 0,
      lifeCelebrator: 0,
      legacyGiver: 0,
      heartGuardian: 0,
      quietPhilosopher: 0
    };

    // Keywords for each archetype
    const archetypeKeywords = {
      peacefulSoul: ['สงบ', 'ธรรมชาติ', 'เงียบ', 'เรียบง่าย', 'จุดจบ', 'พิธีเงียบ'],
      lifeCelebrator: ['สนุก', 'ร่าเริง', 'ปาร์ตี้', 'เฉลิมฉลอง', 'เพลงสนุก', 'กลางคืน'],
      legacyGiver: ['แรงบันดาลใจ', 'ความทรงจำ', 'จดจำ', 'มอบสิ่งของ', 'พัฒนาตัวเอง'],
      heartGuardian: ['ปลอบใจ', 'อบอุ่น', 'ครอบครัว', 'น้ำตา', 'คำพูดซึ้ง', 'รัก'],
      quietPhilosopher: ['เรียบง่าย', 'ศาสนา', 'ลึกซึ้ง', 'จุดเริ่มต้น', 'เขียนจดหมาย']
    };

    // Analyze each answer
    Object.entries(answers).forEach(([questionId, answer]) => {
      if (!answer?.text) return;

      const answerText = answer.text.toLowerCase();
      
      // Check which archetype keywords appear in the answer
      Object.entries(archetypeKeywords).forEach(([archetype, keywords]) => {
        keywords.forEach(keyword => {
          if (answerText.includes(keyword.toLowerCase())) {
            archetypeScores[archetype]++;
          }
        });
      });
    });

    // Find top archetypes
    const sortedArchetypes = Object.entries(archetypeScores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 2);

    return {
      primaryType: sortedArchetypes[0][0],
      secondaryType: sortedArchetypes[1][0],
      scores: archetypeScores
    };
  };

  // Generate personalized summary
  const generateSummary = (personality) => {
    const archetypeSummaries = {
      peacefulSoul: {
        title: "ผู้แสวงหาความสงบ",
        description: "ชีวิตของคุณคือการเดินทางอย่างสงบ คุณต้องการให้งานศพเรียบง่าย เงียบสงบ และเต็มไปด้วยความรักอ่อนโยน"
      },
      lifeCelebrator: {
        title: "ผู้เฉลิมฉลองชีวิต",
        description: "คุณคือคนที่ใช้ชีวิตอย่างเต็มที่ แม้ในวันสุดท้ายคุณก็ยังอยากให้ทุกคนเฉลิมฉลองในแบบของคุณ"
      },
      legacyGiver: {
        title: "ผู้สร้างมรดก",
        description: "คุณเชื่อว่าชีวิตคือการสร้างผลกระทบให้ผู้อื่น คุณอยากให้คนจำคุณในแง่ดีและเรียนรู้จากสิ่งที่คุณทิ้งไว้"
      },
      heartGuardian: {
        title: "ผู้พิทักษ์หัวใจ",
        description: "คุณเป็นคนที่ใส่ใจผู้อื่นลึกซึ้ง ในวันสุดท้ายคุณต้องการให้ทุกคนรู้ว่าความรักยังคงอยู่แม้จากลา"
      },
      quietPhilosopher: {
        title: "นักคิดเงียบ",
        description: "คุณมองความตายอย่างมีความหมาย ไม่ใช่เพียงการจากไปแต่เป็นการส่งต่อความคิดและความรักเงียบ ๆ"
      }
    };

    const primary = archetypeSummaries[personality.primaryType];
    const secondary = archetypeSummaries[personality.secondaryType];

    return {
      title: primary.title,
      description: `${primary.description} ${secondary ? `และ${secondary.description}` : ''}`
    };
  };

  // Get funeral details with enhanced categorization
  const getFuneralDetails = () => {
    const reflectionAnswers = questions
      .filter(q => q.section === 'reflection')
      .map(q => ({ question: q.question, answer: answers[q.id]?.text || 'ไม่ระบุ' }));

    const practicalAnswers = questions
      .filter(q => q.section === 'practical')
      .map(q => ({ question: q.question, answer: answers[q.id]?.text || 'ไม่ระบุ', cost: answers[q.id]?.cost || 0 }));

    // Enhanced style analysis
    const styleCounts = {
      traditional: 0,
      modern: 0,
      minimal: 0,
      luxury: 0
    };

    Object.values(answers).forEach(answer => {
      if (answer?.tags) {
        answer.tags.forEach(tag => {
          if (styleCounts.hasOwnProperty(tag)) {
            styleCounts[tag]++;
          }
        });
      }
    });

    const dominantStyle = Object.entries(styleCounts).reduce((a, b) => a[1] > b[1] ? a : b)[0];
    const styleName = {
      traditional: 'แบบดั้งเดิม',
      modern: 'แบบสมัยใหม่',
      minimal: 'แบบเรียบง่าย',
      luxury: 'แบบหรูหรา'
    }[dominantStyle];

    // Extract specific details for the summary card
    const venue = practicalAnswers.find(a => a.question.includes('จัดที่ไหน'))?.answer || 'ไม่ระบุ';
    const music = practicalAnswers.find(a => a.question.includes('ดนตรี'))?.answer || 'ไม่ระบุ';
    const souvenir = practicalAnswers.find(a => a.question.includes('ของที่ระลึก'))?.answer || 'ไม่ระบุ';
    const atmosphere = reflectionAnswers.find(a => a.question.includes('ความรู้สึก'))?.answer || 'ไม่ระบุ';

    return {
      style: styleName,
      venue,
      music,
      souvenir,
      atmosphere,
      reflection: reflectionAnswers,
      practical: practicalAnswers,
      totalCost
    };
  };

  const personality = analyzePersonality();
  const archetypeKey = personality.primaryType;
  const meta = archetypeMeta[archetypeKey];
  const details = getFuneralDetails();
  const breakEven = Math.ceil(details.totalCost / 1000);

  const cardRef = useRef(null);

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: 'แผนงานศพของฉัน',
        text: `${meta.label} (${meta.eng})\n${meta.hashtags.join(' ')}\nงบประมาณ: ${details.totalCost.toLocaleString()} บาท\nคุ้มทุน: ${breakEven} คน (1,000 บาท/คน)`,
        url: window.location.href
      });
    }
  };

  const handleSaveImage = async () => {
    if (!cardRef.current) return;
    const canvas = await html2canvas(cardRef.current, { backgroundColor: null, scale: 2 });
    const link = document.createElement('a');
    link.download = 'funeral-summary.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-[#e0eafc] to-[#cfdef3] flex items-center justify-center p-4">
      <div
        ref={cardRef}
        className="relative w-full max-w-[400px] h-[500px] mx-auto rounded-3xl shadow-2xl bg-white/80 p-0 overflow-visible flex flex-col justify-between"
        style={{ minHeight: 0, maxHeight: '90vh' }}
      >
        {/* Big Avatar */}
        <div className="flex justify-center -mt-20 mb-2">
          <div className="w-36 h-36 rounded-full bg-white shadow-xl border-4 border-white flex items-center justify-center overflow-hidden">
            <img src={meta.avatar} alt={meta.label} className="object-contain w-32 h-32" />
          </div>
        </div>
        {/* Card Content */}
        <div className="px-6 pb-8 pt-2 flex-1 flex flex-col justify-between">
          {/* Archetype */}
          <div className="text-center mb-2">
            <div className="text-3xl md:text-4xl font-bold text-gray-900">{meta.label}</div>
            <div className="text-base text-gray-500">{meta.eng}</div>
            <div className="flex flex-wrap justify-center gap-2 mt-2">
              {meta.hashtags.map(tag => (
                <span key={tag} className="bg-gray-200 rounded-full px-3 py-1 text-xs font-semibold text-gray-700">{tag}</span>
              ))}
            </div>
          </div>
          {/* Strengths */}
          <div className="bg-white/70 rounded-xl shadow-sm p-4 mt-4 mb-4">
            <div className="font-semibold text-gray-800 mb-2 text-center">จุดเด่นของคุณ</div>
            <ul className="flex flex-wrap justify-center gap-2">
              {meta.strengths.map(str => (
                <li key={str} className="bg-blue-100 rounded-lg px-3 py-1 text-sm text-blue-800">{str}</li>
              ))}
            </ul>
          </div>
          {/* Funeral Style */}
          <div className="bg-blue-50 rounded-xl shadow-sm p-4 mb-4 text-center">
            <div className="text-lg font-medium text-blue-900 italic">“{meta.funeralStyle}”</div>
          </div>
          {/* Funeral Details */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
            <div className="bg-white/80 rounded-xl p-3 text-center">
              <div className="text-xs text-gray-500">📍 สถานที่</div>
              <div className="font-semibold text-gray-900">{details.venue}</div>
            </div>
            <div className="bg-white/80 rounded-xl p-3 text-center">
              <div className="text-xs text-gray-500">🕯️ บรรยากาศ</div>
              <div className="font-semibold text-gray-900">{details.atmosphere}</div>
            </div>
            <div className="bg-white/80 rounded-xl p-3 text-center">
              <div className="text-xs text-gray-500">🎶 ดนตรี</div>
              <div className="font-semibold text-gray-900">{details.music}</div>
            </div>
            <div className="bg-white/80 rounded-xl p-3 text-center">
              <div className="text-xs text-gray-500">🎁 ของที่ระลึก</div>
              <div className="font-semibold text-gray-900">{details.souvenir}</div>
            </div>
          </div>
          {/* Budget */}
          <div className="bg-green-50 rounded-xl p-4 text-center mb-6 shadow-sm">
            <div className="text-lg font-semibold text-green-900 mb-1">💸 งบโดยประมาณ</div>
            <div className="text-2xl font-bold text-green-900 mb-1">{details.totalCost.toLocaleString()} บาท</div>
            <div className="text-gray-700 text-sm">คุ้มทุนที่ {breakEven} คน (บริจาคคนละ 1,000 บาท)</div>
          </div>
          {/* Buttons */}
          <div className="flex flex-col md:flex-row gap-4 mt-2">
            <button onClick={handleShare} className="flex-1 py-3 bg-blue-500 rounded-xl text-white font-semibold hover:bg-blue-600 transition">📤 แชร์บน IG Story</button>
            <button onClick={onRestart} className="flex-1 py-3 bg-gray-200 rounded-xl text-gray-900 font-semibold hover:bg-gray-300 transition">🔄 เริ่มต้นใหม่</button>
            <button onClick={handleSaveImage} className="flex-1 py-3 bg-pink-500 rounded-xl text-white font-semibold hover:bg-pink-600 transition mt-2 md:mt-0">💾 บันทึกเป็นรูปภาพ</button>
          </div>
          {/* Footer */}
          <div className="mt-6 text-center text-xs text-gray-400">#แผนงานศพของฉัน #ชีวิตที่น่าจดจำ</div>
        </div>
      </div>
    </div>
  );
};

export default Summary;
